import math

_ALPHABET_SIZE = 26
_GROUP_SIZE = 5


def _check_coprime(a):
    if math.gcd(a, _ALPHABET_SIZE) != 1:
        raise ValueError("a and m must be coprime.")


def _modular_inverse(a):
    for x in range(_ALPHABET_SIZE):
        if (a * x) % _ALPHABET_SIZE == 1:
            return x
    raise ValueError("a and m must be coprime.")


def encode(plain_text, a, b):
    _check_coprime(a)

    encoded = []
    for char in plain_text.lower():
        if char.isalpha():
            i = ord(char) - ord("a")
            encoded.append(chr((a * i + b) % _ALPHABET_SIZE + ord("a")))
        elif char.isdigit():
            encoded.append(char)

    groups = [
        "".join(encoded[i : i + _GROUP_SIZE])
        for i in range(0, len(encoded), _GROUP_SIZE)
    ]
    return " ".join(groups)


def decode(ciphered_text, a, b):
    _check_coprime(a)

    inverse_a = _modular_inverse(a)
    decoded = []
    for char in ciphered_text:
        if char == " ":
            continue
        if char.isalpha():
            y = ord(char) - ord("a")
            decoded.append(chr(inverse_a * (y - b) % _ALPHABET_SIZE + ord("a")))
        elif char.isdigit():
            decoded.append(char)

    return "".join(decoded)

